// Assume the user types in:
// 4
// 3 17 8 1
// What will be output?
int main() {
    // read the input
    int n;
    cin >> n;
    int data[100]; // declare an array, max size 100
    for (int i = 0; i < n; i++)
        cin >> data[i]; // read elements of data from input

    for(int i=0; i < n; i++){
        int temp = data[i];
        data[i] = data[n-i-1];
        data[n-i-1] = temp;
    }

    for (int i = 0; i < n; i++)
        cout << data[i] << " ";

    return 0;
}
The program reads n=4 and array {3, 17, 8, 1}. The swap loop iterates over all n elements rather than n/2, so it reverses the array and then reverses it back, resulting in the original order: 3 17 8 1.

#include <iostream>
using namespace std;

void f1(int d[], int n, int x);
int f2(int d[], int a, int b);
int f3(int a, int b, int c);

void f1(int d[], int n, int x)
{
  for(int i=0; i <= n/x; i++){
    d[i] = x*x;
  }
}

int f2(int d[], int a, int b)
{
  int sum = 0;
  for(int i=a; i < b; i++){
    if( d[i] % 2 == 0 ){
      sum += d[i];
    }
  }
  return sum;
}

int f3(int a, int b, int c)
{
  if( a % b == 0) {
    c += 2;
    return b;
  }
  else if( a % c == 0) {
    b -= 1;
    return c;
  }
  return a;
}

int main()
{
  int dat[8] = { 2, 5, 6, 8, 2, 4, 2, 12};
  f1(dat, 8, f3(dat[7], dat[1], 3));
  cout << f2(dat, 1, 6) << endl;
  for(int i=0; i < 8; i++){
    cout << dat[i] << " ";
  }
  cout << endl;
  return 0;
}
